function largestRectangleArea(heights) {
  const n = heights.length;
  const left = new Array(n).fill(-1);      // nearest shorter bar on the left
  const right = new Array(n).fill(n);      // nearest shorter bar on the right
  let stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && heights[stack[stack.length - 1]] >= heights[i]) stack.pop();
    if (stack.length > 0) left[i] = stack[stack.length - 1];
    stack.push(i);
  }
  stack = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length > 0 && heights[stack[stack.length - 1]] >= heights[i]) stack.pop();
    if (stack.length > 0) right[i] = stack[stack.length - 1];
    stack.push(i);
  }
  let best = 0;
  for (let i = 0; i < n; i++) {
    best = Math.max(best, heights[i] * (right[i] - left[i] - 1));   // bar i at full height
  }
  return best;
}

def largest_rectangle_area(heights):
    n = len(heights)
    left = [-1] * n                          # nearest shorter bar on the left
    right = [n] * n                          # nearest shorter bar on the right
    stack = []
    for i in range(n):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            left[i] = stack[-1]
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if stack:
            right[i] = stack[-1]
        stack.append(i)
    return max((heights[i] * (right[i] - left[i] - 1) for i in range(n)), default=0)

public int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n], right = new int[n];   // nearest shorter bar on each side
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) stack.pop();
        left[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }
    stack.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) stack.pop();
        right[i] = stack.isEmpty() ? n : stack.peek();
        stack.push(i);
    }
    int best = 0;
    for (int i = 0; i < n; i++) {
        best = Math.max(best, heights[i] * (right[i] - left[i] - 1));   // bar i at full height
    }
    return best;
}

